A function declaration is hoisted, so it can sit at the bottom of the file and still be called at the top. Put the log inside so the function returns nothing useful.

code:
function greet(name) {
  console.log('Hello, ' + name + '!');
}

greet('Ana');
greet('Bob');

output:
Hello, Ana!
Hello, Bob!

A function expression is a value, so it needs a const to live in. It is not hoisted as a usable value, only the const name is.

code:
const double = function (n) {
  return n * 2;
};

console.log(double(21));

output:
42

An arrow function drops the function keyword and moves the parameter straight into the parentheses. The body stays the same.

code:
const add = (a, b) => {
  return a + b;
};

console.log(add(2, 3));
console.log(typeof add);

output:
5
function

Function declarations are hoisted to the top of the scope with their body attached, so calling logMe before the line that defines it works.

code:
logMe('first');

function logMe(msg) {
  console.log('logMe says ' + msg);
}

logMe('second');

output:
logMe says first
logMe says second

A const is hoisted but starts in the temporal dead zone, so touching it before the line that assigns it throws. The second call works.

code:
try {
  shout();
} catch (err) {
  console.log('caught: ' + err.constructor.name);
}

const shout = function () {
  console.log('hi');
};

shout();

output:
caught: ReferenceError
hi

Map is a higher-order function: it takes a callback and hands it each item. The array literal lives inside the snippet so it is self-contained.

code:
function multiplyAll(nums, factor) {
  return nums.map((n) => n * factor);
}

const nums = [1, 2, 3];
console.log(multiplyAll(nums, 10));
console.log(nums);

output:
[ 10, 20, 30 ]
[ 1, 2, 3 ]

Recursion is a function calling itself with a smaller input. The base case stops the chain, and it must come before the recursive call.

code:
function factorial(n) {
  if (n <= 1) {
    return 1;
  }
  return n * factorial(n - 1);
}

console.log(factorial(6));
console.log(factorial(0));

output:
720
1

Keep the last two values in variables and shift them each round. That turns the exponential recursion into linear work.

code:
function fib(n) {
  let a = 0;
  let b = 1;
  for (let i = 0; i < n; i++) {
    const next = a + b;
    a = b;
    b = next;
  }
  return a;
}

console.log(fib(7));
console.log(fib(1));

output:
13
1

The name property is read from the variable name when the function has no name of its own. A named function expression keeps its own name.

code:
const anon = function () {};
const inner = function inner() {};
const arrow = () => {};

console.log(anon.name);
console.log(inner.name);
console.log(arrow.name);

output:
anon
inner
arrow

The length property counts parameters before the first one with a default value. Defaults break the count, rest parameters are not counted at all.

code:
function none() {}
function two(a, b) {}
function withDefault(a, b = 1) {}
function withRest(...rest) {}

console.log(none.length);
console.log(two.length);
console.log(withDefault.length);
console.log(withRest.length);

output:
0
2
1
0

An IIFE runs as soon as it is defined and its inner names never leak into the outer scope. The return value is the only public part.

code:
const report = (function () {
  const items = [4, 8, 15];
  const total = items.reduce((a, b) => a + b, 0);
  return { count: items.length, total: total };
})();

console.log(report);
console.log(typeof report.missing);

output:
{ count: 3, total: 27 }
undefined

The counter variable lives inside the IIFE, so each method closes over the same hidden number. That is module privacy without modules.

code:
const box = (function () {
  let count = 0;
  return {
    inc() {
      count = count + 1;
      return count;
    },
    get() {
      return count;
    },
  };
})();

box.inc();
console.log(box.inc());
console.log(box.get());

output:
2
2

A normal method gets its this from the dot before the call. Detaching the method loses that dot, so this falls back to undefined.

code:
const bot = {
  name: 'unit-3',
  describe() {
    return 'I am ' + this.name;
  },
};

console.log(bot.describe());
const detached = bot.describe;
console.log(detached());

output:
I am unit-3
I am undefined

bind returns a new function with this and any first argument locked in. It is the cheap way to keep a method working after you move it.

code:
function greetUser(name) {
  return 'Hi ' + name + ' from ' + this.app;
}

const api = { app: 'shop', greetUser: greetUser };
console.log(api.greetUser('Ana'));
const bound = greetUser.bind(api);
console.log(bound('Bob'));

output:
Hi Ana from shop
Hi Bob from shop

The returned function keeps a reference to the number passed to makeAdder. Each call of makeAdder makes a fresh, separate box.

code:
function makeAdder(base) {
  return function (extra) {
    return base + extra;
  };
}

const addFive = makeAdder(5);
console.log(addFive(3));
console.log(addFive(10));

output:
8
15

Passing a function as an argument and calling it inside is what makes it higher-order. A for loop drives the calls.

code:
function repeat(times, fn) {
  for (let i = 1; i <= times; i++) {
    fn(i);
  }
}

repeat(3, (step) => {
  console.log('step ' + step);
});

output:
step 1
step 2
step 3

Map does the looping for you and the callback does the work. Returning the array from map keeps the function pure.

code:
function applyAll(nums, fn) {
  return nums.map(fn);
}

const double = (n) => n * 2;
console.log(applyAll([1, 2, 3], double));
console.log(applyAll([1, 2, 3], (n) => n + 100));

output:
[ 2, 4, 6 ]
[ 101, 102, 103 ]

A rest parameter collects the leftover arguments into a real array, so reduce is available. Calling with no arguments gives an empty array.

code:
function sumAll(...nums) {
  return nums.reduce((a, b) => a + b, 0);
}

console.log(sumAll(1, 2, 3));
console.log(sumAll());
console.log(sumAll(10));

output:
6
0
10

split turns the string into an array of single characters, then filter keeps the ones you want and length counts them.

code:
function countChars(text, letter) {
  return text.split('').filter((c) => c === letter).length;
}

console.log(countChars('banana', 'a'));
console.log(countChars('test run', 't'));

output:
3
2

typeof gives a quick category for any value, including functions. Returning a separate value keeps the log and the result separate.

code:
function describe(value) {
  console.log('type is ' + typeof value);
  return 'done';
}

console.log(describe(42));
console.log(describe('hi'));
console.log(describe(describe));

output:
type is number
done
type is string
done
type is function
done

throw stops the function immediately. A try and catch around the call lets the program print something useful instead of crashing.

code:
function assertPositive(n) {
  if (n <= 0) {
    throw new Error('value must be positive');
  }
  return 'ok';
}

console.log(assertPositive(5));
try {
  assertPositive(0);
} catch (err) {
  console.log('caught: ' + err.message);
}

output:
ok
caught: value must be positive

Keeping the conversion pure and the printing separate makes both easy to test. ForEach drives the table.

code:
function toFahrenheit(c) {
  return (c * 9) / 5 + 32;
}

function table(celsius) {
  celsius.forEach((c) => {
    console.log(c + 'C = ' + toFahrenheit(c) + 'F');
  });
}

table([0, 100]);

output:
0C = 32F
100C = 212F

Rest collects the arguments, then entries gives index and value pairs. This is a tiny stand-in for a real logging helper.

code:
function logAll(...args) {
  console.log(args.length + ' args');
  args.forEach((arg, i) => {
    console.log(i + ': ' + arg);
  });
}

logAll('a', 'b', 'c');
logAll();

output:
3 args
0: a
1: b
2: c
0 args

A named function expression can call itself because the name lives in its own scope. This is why it is more than decoration.

code:
const factorial = function fact(n) {
  return n <= 1 ? 1 : n * fact(n - 1);
};

console.log(factorial(4));
console.log(factorial.name);

output:
24
fact

The outer function takes the first argument and returns a function waiting for the second. Nothing runs until both calls happen.

code:
function curryAdd(fn) {
  return function curried(a) {
    return function (b) {
      return fn(a, b);
    };
  };
}

const add = (a, b) => a + b;
const curried = curryAdd(add);
console.log(curried(2)(3));
console.log(curried(10)(5));

output:
5
15

Returning a function from a function lets you configure sorting in two steps. Subtracting the values gives the ascending order.

code:
function sortByKey(key) {
  return function (a, b) {
    return a[key] - b[key];
  };
}

const people = [
  { name: 'B', age: 30 },
  { name: 'A', age: 20 },
];

console.log(people.slice().sort(sortByKey('age')));
console.log(people.slice().sort(sortByKey('age')).map((p) => p.name));

output:
[ { name: 'A', age: 20 }, { name: 'B', age: 30 } ]
[ 'A', 'B' ]

Reduce can carry the running best value as its accumulator. Starting from the first argument avoids the empty case being an infinite value.

code:
function maxOf(...nums) {
  return nums.reduce((best, n) => (n > best ? n : best), nums[0]);
}

console.log(maxOf(3, 9, 4));
console.log(maxOf(-5, -2));

output:
9
-2

An array of functions plus reduce lets you chain them without nesting calls. The accumulator is the running value.

code:
function pipeResult(value, fns) {
  return fns.reduce((acc, fn) => fn(acc), value);
}

const double = (n) => n * 2;
const addOne = (n) => n + 1;

console.log(pipeResult(5, [double, addOne]));
console.log(pipeResult(5, [addOne, double]));

output:
11
12

Reading a missing key gives undefined rather than an error, so a simple comparison covers the default case.

code:
function getOrDefault(obj, key, fallback) {
  if (obj[key] === undefined) {
    return fallback;
  }
  return obj[key];
}

const user = { name: 'Cid' };
console.log(getOrDefault(user, 'name', 'anonymous'));
console.log(getOrDefault(user, 'email', 'none'));
console.log(getOrDefault({ role: null }, 'role', 'user'));

output:
Cid
none
null

A normal method builds its own this from the call site, while an arrow captures this from where it was written. Detaching hurts only the normal one.

code:
const timer = {
  value: 5,
  sync() {
    console.log('sync ' + this.value);
  },
  arrow: () => {
    console.log('arrow ' + this.value);
  },
};

timer.sync();
const loose = timer.sync;
loose();
timer.arrow();

output:
sync 5
sync undefined
arrow undefined

Keeping the prefix outside and the id inside means the id stays local. Each returned function knows the prefix from creation time.

code:
function tagger(prefix) {
  return function (id) {
    return prefix + '-' + id;
  };
}

const user = tagger('user');
console.log(user(1));
console.log(user(2));
console.log(tagger('order')(7));

output:
user-1
user-2
order-7

Small pure functions are easy to test one at a time. Chaining means the second function only handles the string.

code:
function parity(n) {
  const label = n % 2 === 0 ? 'even' : 'odd';
  console.log(label);
  return label;
}

function shout(text) {
  return text.toUpperCase();
}

console.log(shout(parity(4)));
console.log(shout(parity(7)));

output:
even
EVEN
odd
ODD

An array of functions is a tiny task list. forEach runs them in order and gives you the index for free.

code:
function runAll(fns) {
  fns.forEach((fn, i) => {
    console.log(i + ' returned ' + fn());
  });
}

runAll([
  () => 'first',
  () => 'second',
]);

output:
0 returned first
1 returned second

Test divisibility only up to the square root of the number. isPrime stays separate so you can reuse it elsewhere.

code:
function isPrime(n) {
  if (n < 2) return false;
  for (let d = 2; d * d <= n; d++) {
    if (n % d === 0) return false;
  }
  return true;
}

function primesUpTo(limit) {
  const found = [];
  for (let n = 2; n < limit; n++) {
    if (isPrime(n)) found.push(n);
  }
  return found;
}

console.log(primesUpTo(12));

output:
[ 2, 3, 5, 7, 11 ]

Split on spaces, then reduce once to find the longest word. Doing it in a single pass keeps it readable.

code:
function wordCount(sentence) {
  const words = sentence.split(' ');
  return words.reduce(
    (acc, w) => ({ words: acc.words + 1, longest: w.length > acc.longest.length ? w : acc.longest }),
    { words: 0, longest: '' }
  );
}

console.log(wordCount('the quick brown fox'));

output:
{ words: 4, longest: 'quick' }

Math.max with the lower bound first and Math.min with the upper bound second gives both ends in one line.

code:
function clamp(n, low, high) {
  return Math.min(Math.max(n, low), high);
}

console.log(clamp(120, 0, 100));
console.log(clamp(-5, 0, 100));
console.log(clamp(50, 0, 100));

output:
100
0
50

A rest parameter captures whatever was passed, so the wrapper works for any argument list. It returns the original result so behaviour is unchanged.

code:
function withLogging(fn) {
  return function (...args) {
    console.log('calling with ' + args.join(','));
    const result = fn(...args);
    console.log('returned ' + result);
    return result;
  };
}

const double = (n) => n * 2;
console.log(withLogging(double)(21));

output:
calling with 21
returned 42
42

concat with an empty array adds each element, and it flattens one level only. Nested arrays deeper than that stay nested.

code:
function flattenOnce(nested) {
  return nested.reduce((acc, item) => acc.concat(item), []);
}

console.log(flattenOnce([1, [2, 3], [[4]]]));
console.log(flattenOnce([]));

output:
[ 1, 2, 3, [ 4 ] ]
[]
